def B(n):return (P/n).read_bytes()
def J(n):return json.loads(B(n))
def H(b):return hashlib.sha256(b).hexdigest()
def S(v,n):return (v^(1<<(n-1)))-(1<<(n-1))
def flow(w,pc):
 if w&0x7c000000==0x14000000:return {'kind':'BL' if w>>31 else 'B','target':pc+4*S(w&0x3ffffff,26)}
 if w&0xff000010==0x54000000:return {'kind':'Bcond','condition':w&15,'target':pc+4*S((w>>5)&0x7ffff,19)}
 if w&0x7e000000==0x34000000:return {'kind':'CB','rt':w&31,'nonzero':bool(w&(1<<24)),'target':pc+4*S((w>>5)&0x7ffff,19)}
 if w&0x7e000000==0x36000000:return {'kind':'TB','rt':w&31,'bit':(w>>31)*32+((w>>19)&31),'target':pc+4*S((w>>5)&0x3fff,14)}
 k=w&0xfffffc1f
 if k in [0xd61f0000,0xd63f0000,0xd65f0000]:return {'kind':{0xd61f0000:'BR',0xd63f0000:'BLR',0xd65f0000:'RET'}[k],'register':(w>>5)&31}
def load(w):
 assert w&0xffc00000==0xf9400000
 return (w&31,(w>>5)&31,((w>>10)&4095)*8)
def association(r,b,pc):assert type(r['offset']) is int and r['offset']==pc and type(r['size']) is int and r['size']==4 and bytes.fromhex(r['bytes'])==b
