assert len(m['files'])==54 and sum(x['bytes'] for x in m['files'])==240836
for x in m['files']:
 b=B(x['path']);assert len(b)==x['bytes'] and H(b)==x['sha256'] and stat.S_IMODE((P/x['path']).stat().st_mode)==0o444
assert {x['path'] for x in m['files']}=={str(x.relative_to(P)) for x in P.rglob('*') if x.is_file() and x.name!='manifest.json'}
