assert before==[plan['image'],plan['tool'],*plan['pins'],{'path':str(P/'pre-call-manifest.json'),'bytes':7321,'sha256':H(B('pre-call-manifest.json'))}]
W={};flows=[];pairs=[];addresses=[];literals=[];receipts=[];bodies=[]
for r in plan['ranges']:
 s=int(r['start'],16);e=int(r['end_exclusive'],16);key=f'{s:x}';rows=J(f'capture/{key}.stdout.json');raw=B(f'capture/{key}.bin')
 assert len(raw)==r['bytes']==e-s==4*len(rows) and r['file_offset']==s and 0x15e0<=s<e<=0x15e0+324100
 for i,row in enumerate(rows):
  pc=s+4*i;association(row,raw[i*4:i*4+4],pc);w=int.from_bytes(raw[i*4:i*4+4],'little');W[pc]=w
  f=flow(w,pc)
  if f:
   if 'target' in f:assert row.get('jump')==f['target']
   else:assert row['opcode'].split()[0]==f['kind'].lower()
   flows.append({'pc':hex(pc),'raw':f'{w:08x}',**f})
  if w&0x1f000000==0x10000000:
   imm=S((((w>>5)&0x7ffff)<<2)|((w>>29)&3),21);a=(pc&~4095)+(imm<<12) if w>>31 else pc+imm
   assert row.get('ptr')==a;addresses.append({'pc':hex(pc),'address':hex(a),'rd':w&31})
  if w&0x3b000000==0x18000000:
   a=pc+4*S((w>>5)&0x7ffff,19);assert row.get('ptr')==a;literals.append({'pc':hex(pc),'literal_address_only':hex(a),'contents_read':False})
  if w&0x3e000000==0x28000000 and not w&(1<<26) and (w>>30)&3==2:
   pairs.append({'pc':hex(pc),'load':bool(w&(1<<22)),'base':(w>>5)&31,'rt':w&31,'rt2':(w>>10)&31,'offset':S((w>>15)&127,7)*8,'mode':(w>>23)&3})
 b=J(f'capture/{key}.invocation-before.json');a=J(f'capture/{key}.invocation-after.json');pid=J(f'capture/{key}.pid.json')
 assert a['argv']==b['argv']==pid['argv']==[plan['tool']['path'],'-NN','-n','-x','-f','-a','arm','-b','64','-E','little','-m',hex(s),'-s',hex(s),'-q','-c',f'pdj {len(rows)}',str(P/'capture'/f'{key}.bin')]
 assert b['pid'] is None and b['exit_code'] is None and b['started_utc']==a['started_utc']<pid['spawned_utc']<a['finished_utc']
 assert a['pid']==pid['pid']==pid['pgid'] and a['exit_code']==0 and a['error'] is None and not a['timed_out'] and a['cleanup']=='process-group-already-gone' and B(f'capture/{key}.stderr')==b''
 assert a['environment']=={'PATH':'/usr/bin:/bin','LANG':'C.UTF-8','LC_ALL':'C.UTF-8','TZ':'UTC'} and a['stdin']=='DEVNULL' and a['core_limit_bytes']==0 and a['new_process_session']
 receipts.append({'start':a['started_utc'],'end':a['finished_utc'],'pid':a['pid'],'entry':hex(s)});bodies.append({'entry':hex(s),'end_exclusive':hex(e),'rows':len(rows),'bytes':len(raw),'sha256':H(raw)})
