ind=[x for x in flows if x['kind'] in ['BR','BLR']];assert {int(x['pc'],16):(x['kind'],x['register']) for x in ind}=={0x19a44:('BR',4),0x19a5c:('BR',4),0x19abc:('BR',1),0x19b3c:('BR',1),0x19f90:('BLR',8),0x1a138:('BR',1),0x1a19c:('BR',2)}
sources=B('source-context.jsonl').splitlines(keepends=True);meta=J('selected-metadata.json')['records'];Cbytes=Clines=warnings=0
for b,r in zip(sources,meta):
 mm=r['C1_metadata_only'];d=json.loads(b);code=d.pop('code');assert len(b)==mm['raw_bytes'] and H(b)==mm['raw_sha256'] and d==mm['metadata'];assert len(code.encode())==d['code_bytes'] and H(code.encode())==d['code_sha256']
 Cbytes+=len(code.encode());Clines+=len(code.splitlines());warnings+=len(d['warnings'])
